from collections import deque


class ConnectGame:
    def __init__(self, board):
        self.board = [line.split() for line in board.splitlines() if line.strip()]

    def get_winner(self):
        for player in ("X", "O"):
            if self._connects(player):
                return player
        return ""

    def _connects(self, player):
        rows = len(self.board)
        if rows == 0:
            return False
        cols = [len(row) for row in self.board]

        if player == "X":
            # X connects the left edge to the right edge.
            start = [(r, 0) for r in range(rows) if self.board[r][0] == player]
            is_goal = lambda r, c: c == cols[r] - 1
        else:
            # O connects the top edge to the bottom edge.
            start = [(0, c) for c in range(cols[0]) if self.board[0][c] == player]
            is_goal = lambda r, c: r == rows - 1

        seen = set(start)
        queue = deque(start)
        while queue:
            r, c = queue.popleft()
            if is_goal(r, c):
                return True
            for nr, nc in self._neighbors(r, c, rows, cols):
                if (nr, nc) not in seen and self.board[nr][nc] == player:
                    seen.add((nr, nc))
                    queue.append((nr, nc))
        return False

    def _neighbors(self, r, c, rows, cols):
        for nr, nc in ((r, c - 1), (r, c), (r - 1, c - 1), (r - 1, c),
                       (r + 1, c - 1), (r + 1, c)):
            if 0 <= nr < rows and 0 <= nc < cols[nr]:
                yield nr, nc

